import time
import uuid
from typing import Any, Dict, Optional

from cortex.proposal_api import OrderDirection, TradeProposal


class CortexEngine:
    """
    The quantitative intelligence swarm. Analyzes normalized market ticks and
    emits validated TradeProposal objects. It has zero execution privileges —
    every proposal must be adjudicated by the Iron Constitution risk core.
    """

    SIZING_MULTIPLIER = 0.05  # baseline position sizing rule (5% of equity)

    def __init__(self, asset_id: str, risk_profile: str = "dynamic"):
        self.asset_id = asset_id
        self.risk_profile = risk_profile

    def evaluate_market_tick(self, market_data: Dict[str, Any]) -> Dict[str, Any]:
        current_price = float(market_data.get("price", 0.0) or 0.0)
        equity = float(market_data.get("account_equity", 10000.0) or 10000.0)
        momentum = bool(market_data.get("momentum_signal", False))

        if not momentum or current_price <= 0.0:
            return {"status": "NoAction", "proposal": None}

        trend = str(market_data.get("trend", "neutral")).lower()
        if trend not in ("bullish", "bearish"):
            return {"status": "NoAction", "proposal": None}

        danger_zone = market_data.get("volatility", 0.0)
        try:
            danger_zone = float(danger_zone)
        except (TypeError, ValueError):
            danger_zone = 0.0

        sizing = CortexEngine.SIZING_MULTIPLIER
        if danger_zone > 0.02:
            sizing *= 0.5  # halve size in elevated volatility regimes

        proposal = TradeProposal(
            proposal_id=str(uuid.uuid4()),
            asset_id=self.asset_id,
            direction=(
                OrderDirection.BUY if trend == "bullish" else OrderDirection.SELL
            ),
            target_notional=round(max(equity * sizing, 1.0), 2),
            max_acceptable_slippage=0.0015,
        )

        return {
            "status": "ProposalGenerated",
            "timestamp": int(time.time()),
            "proposal": proposal.model_dump(),
        }